WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_solution_expand'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '对策扩充与可行性', 'kp-sl-solution-expand', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "对策扩充与可行性"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "致命要求：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "你提的对策在现实中能落地吗？是否合法合规？"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "提出假大空或违法的对策：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比如为了解决闯红灯问题，你提出“闯红灯一律拘留判刑”。这严重违背了法律的比例原则，不可行，直接零分！对策必须符合政府部门的【实际操作权限】和【成本效益】。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、扩充万能模板"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当材料找不到词时，用这 5 个维度去扩充：思想认识、法律制度、监管执行、资金技术、人才队伍。"}]}]}$$ AS jsonb), NULL, '对策扩充与可行性的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "提出对策", "可行性"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_solution_expand", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
